    private const string Prefix = "D5/S1/Recurrence/Periodic/AutonomousDerivationTotientSquarePeriod.";

    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Totient-square periods of integral derivation coefficients.",
        H("Integral Derivations and Prime-Power Periods"),
        Blocks(
            Node("BalaCharP.iterate_leibniz", "iterate leibniz", Formula0(),
                "Iterating a derivation distributes over products with binomial coefficients.", DescribeRole.Theorem, AssessedProvenance.FromRepo()),
            Node("BalaJets.root_pow_zero", "root pow zero", Formula1(),
                "The root of X to the power L is nilpotent of exponent L.", DescribeRole.Theorem, AssessedProvenance.FromRepo()),
            Node("BalaJets.jetDerivation", "jetDerivation", Formula2(),
                "Choose a quotient derivation with the action specified by existsJetDerivation.", DescribeRole.Definition, AssessedProvenance.FromRepo()),
            Node("BalaJets.jetDerivation_root", "jetDerivation root", Formula3(),
                "The quotient derivation sends its coordinate to the polynomial P.", DescribeRole.Theorem, AssessedProvenance.FromRepo()),
            Node("BalaTruncated.matrix", "matrix", Formula4(),
                "The finite derivation operator is represented in the standard coefficient basis.", DescribeRole.Definition, AssessedProvenance.FromRepo()),
            Node("BalaTruncated.matrix_natural", "matrix natural", Formula5(),
                "Changing coefficients commutes with forming the truncated derivation matrix.", DescribeRole.Theorem, AssessedProvenance.FromRepo()),
            Node("BalaTruncated.integer_matrix_totient_square", "integer matrix totient square", Formula6(),
                "The characteristic-p filtration and integral matrix lift give the prescribed totient-square annihilator at each prime power.", DescribeRole.Theorem, AssessedProvenance.FromRepo()),
            Node("BalaTruncated.jet_annihilator_of_matrix", "jet annihilator of matrix", Formula7(),
                "A matrix annihilator transfers to every element of the truncated polynomial ring.", DescribeRole.Theorem, AssessedProvenance.FromRepo()),
            Node("BalaTruncated.prime_power_derivative_period", "prime power derivative period", Formula8(),
                "Every integral polynomial observable has the stated derivative-index period after the explicit prime-power threshold.", DescribeRole.Theorem, AssessedProvenance.FromRepo()),
            Node("BalaOddPrimeRoot.square_root_in_finite_jet", "square root in finite jet", Formula9(),
                "At an odd prime, a suitable power of one plus a nilpotent is its square root.", DescribeRole.Theorem, AssessedProvenance.FromRepo()),
            Node("BalaTruncated.truncation", "truncation", Formula10(),
                "A polynomial linear operator acts on the finite coefficient space by encoding and decoding.", DescribeRole.Definition, AssessedProvenance.FromRepo()),
            Node("BalaLinearTruncation.decode_zero_iff", "decode zero iff", Formula11(),
                "Vanishing of the first L coefficients is divisibility by X to the power L.", DescribeRole.Theorem, AssessedProvenance.FromRepo()),
            Node("BalaLinearTruncation.decode_semiconj", "decode semiconj", Formula12(),
                "An operator preserving the truncation ideal commutes with coefficient truncation.", DescribeRole.Theorem, AssessedProvenance.FromRepo()),
            Node("BalaLinearTruncation.secondOrder", "secondOrder", Formula13(),
                "This is the linear operator a times the second derivative plus b times the first derivative.", DescribeRole.Definition, AssessedProvenance.FromRepo()),
            Node("BalaLinearTruncation.secondOrder_apply", "secondOrder apply", Formula14(),
                "Evaluation of the second-order operator gives its two differential terms.", DescribeRole.Theorem, AssessedProvenance.FromRepo()),
            Node("BalaLinearTruncation.secondOrder_stable", "secondOrder stable", Formula15(),
                "If the scalar L vanishes, both derivatives preserve the ideal generated by X to the power L.", DescribeRole.Theorem, AssessedProvenance.FromRepo()),
            Node("BalaSecondOrderMatrix.secondOrderMatrix", "secondOrderMatrix", Formula16(),
                "Represent the truncated second-order operator in the standard coefficient basis.", DescribeRole.Definition, AssessedProvenance.FromRepo()),
            Node("BalaSecondOrderMatrix.secondOrderMatrix_natural", "secondOrderMatrix natural", Formula17(),
                "The second-order matrix also commutes with changing coefficients.", DescribeRole.Theorem, AssessedProvenance.FromRepo()),
            Node("BalaSecondOrderMatrix.integral_annihilator", "integral annihilator", Formula18(),
                "In characteristic two the second derivative vanishes; the first-order matrix theorem and integral lift then supply this annihilator.", DescribeRole.Theorem, AssessedProvenance.FromRepo()),
            Node("BalaJets.existsJetDerivation", "existsJetDerivation", Formula19(),
                "The polynomial derivation preserves the quotient ideal and therefore induces a derivation with the displayed action on every polynomial class.", DescribeRole.Theorem, AssessedProvenance.FromRepo()))));

